      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "Result: all of these conditions hold: [the fact actor_offers_component_to_client; the fact component_is_gift; it is not the case that [the fact component_is_fee_or_charge_discount]; at least one of these conditions holds: [the fact component_promotes_specific_product; the fact component_promotes_product_type]]"
